# Simple Python Calculator

Here's a complete calculator with multiple features:

## **Basic Calculator**

```python
def add(x, y):
    return x + y

def subtract(x, y):
    return x - y

def multiply(x, y):
    return x * y

def divide(x, y):
    if y == 0:
        return "Error: Cannot divide by zero"
    return x / y

def calculator():
    print("=" * 40)
    print("         SIMPLE CALCULATOR")
    print("=" * 40)

    while True:
        print("\nSelect operation:")
        print("1. Add")
        print("2. Subtract")
        print("3. Multiply")
        print("4. Divide")
        print("5. Exit")

        choice = input("\nEnter choice (1/2/3/4/5): ")

        if choice == '5':
            print("Thank you for using the calculator!")
            break

        if choice in ('1', '2', '3', '4'):
            try:
                num1 = float(input("Enter first number: "))
                num2 = float(input("Enter second number: "))

                if choice == '1':
                    print(f"\n{num1} + {num2} = {add(num1, num2)}")
                elif choice == '2':
                    print(f"\n{num1} - {num2} = {subtract(num1, num2)}")
                elif choice == '3':
                    print(f"\n{num1} × {num2} = {multiply(num1, num2)}")
                elif choice == '4':
                    result = divide(num1, num2)
                    print(f"\n{num1} ÷ {num2} = {result}")
            except ValueError:
                print("Invalid input! Please enter numeric values.")
        else:
            print("Invalid choice! Please select a valid operation.")

if __name__ == "__main__":
    calculator()
```

---

## **Advanced Calculator (with more operations)**

```python
import math

class Calculator:
    def __init__(self):
        self.result = 0

    def add(self, x, y):
        self.result = x + y
        return self.result

    def subtract(self, x, y):
        self.result = x - y
        return self.result

    def multiply(self, x, y):
        self.result = x * y
        return self.result

    def divide(self, x, y):
        if y == 0:
            return "Error: Cannot divide by zero"
        self.result = x / y
        return self.result

    def power(self, x, y):
        self.result = x ** y
        return self.result

    def square_root(self, x):
        if x < 0:
            return "Error: Cannot find square root of negative number"
        self.result = math.sqrt(x)
        return self.result

    def percentage(self, x, y):
        self.result = (x / 100) * y
        return self.result

def advanced_calculator():
    calc = Calculator()

    print("=" * 50)
    print("         ADVANCED CALCULATOR")
    print("=" * 50)

    while True:
        print("\nOperations:")
        print("1. Add")
        print("2. Subtract")
        print("3. Multiply")
        print("4. Divide")
        print("5. Power (x^y)")
        print("6. Square Root")
        print("7. Percentage")
        print("8. Exit")
        print(f"\nCurrent Result: {calc.result}")

        choice = input("\nSelect operation (1-8): ")

        if choice == '8':
            print("Thank you for using the calculator!")
            break

        try:
            if choice in ('1', '2', '3', '4', '5', '7'):
                num1 = float(input("Enter first number: "))
                num2 = float(input("Enter second number: "))

                if choice == '1':
                    print(f"\nResult: {calc.add(num1, num2)}")
                elif choice == '2':
                    print(f"\nResult: {calc.subtract(num1, num2)}")
                elif choice == '3':
                    print(f"\nResult: {calc.multiply(num1, num2)}")
                elif choice == '4':
                    print(f"\nResult: {calc.divide(num1, num2)}")
                elif choice == '5':
                    print(f"\nResult: {calc.power(num1, num2)}")
                elif choice == '7':
                    print(f"\nResult: {calc.percentage(num1, num2)}% of {num2}")

            elif choice == '6':
                num = float(input("Enter number: "))
                print(f"\nResult: {calc.square_root(num)}")
            else:
                print("Invalid choice!")

        except ValueError:
            print("Invalid input! Please enter numeric values.")

if __name__ == "__main__":
    advanced_calculator()
```

---

## **One-Line Expression Calculator**

```python
def eval_calculator():
    print("=" * 40)
    print("    EXPRESSION CALCULATOR")
    print("=" * 40)
    print("Type your expression (e.g., 5 + 3 * 2)")
    print("Type 'exit' to quit\n")

    while True:
        expression = input("Enter expression: ")

        if expression.lower() == 'exit':
            print("Thank you for using the calculator!")
            break

        try:
            result = eval(expression)
            print(f"Result: {result}\n")
        except Exception as e:
            print(f"Error: {e}\n")

if __name__ == "__main__":
    eval_calculator()
```

---

## **How to Run:**

1. **Save the code** to a file (e.g., `calculator.py`)
2. **Run it** using:
   ```bash
   python calculator.py
   ```

---

Choose the version you prefer:
- **Basic Calculator**: Simple and straightforward
- **Advanced Calculator**: More features with a class-based approach
- **Expression Calculator**: Type mathematical expressions directly

Which one would you like to use? 🧮

